(()=>{const album=document.querySelector('.photo-album');if(!album)return;const pages=[...album.querySelectorAll('.album-spread')],status=album.querySelector('.album-status'),buttons=[...album.querySelectorAll('[data-page-step]')];if(!pages.length)return;let current=0;function show(index){current=Math.max(0,Math.min(pages.length-1,index));pages.forEach((p,i)=>p.hidden=i!==current);status.textContent=`${current+1} / ${pages.length}`;buttons[0].disabled=current===0;buttons[1].disabled=current===pages.length-1;pages[current].querySelector('img').loading='eager';}buttons.forEach(b=>b.addEventListener('click',()=>show(current+Number(b.dataset.pageStep))));album.tabIndex=0;album.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1));}});let start;album.addEventListener('touchstart',e=>{if(e.touches.length===1)start={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});album.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;start=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)show(current+(dx<0?1:-1));},{passive:true});album.classList.add('album-ready');show(0);})();

